import { Group, Mesh, BoxGeometry, PlaneGeometry, PointLight, Color, SRGBColorSpace, RepeatWrapping, DoubleSide } from 'three/webgpu';
import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, float, length, smoothstep, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const colors = config?.intent?.visualSpec?.colors ?? config?.colors ?? {
    ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10',
  };

  const items = config.textContent ?? config?.intent?.visualSpec?.textContent ?? [];
  const label = items.find((i) => i.role === 'headline') ?? items[0] ?? { text: 'Get started', typography: { fontSize: 42 } };
  const labelText = (label.text ?? 'Get started').replace(/[^\x00-\x7F]/g, '');
  const fontSizePx = label.typography?.fontSize ?? 42;

  const root = new Group();
  root.name = 'cta-label';

  // local animation wrapper — adapter owns root's transform (scenePosition)
  const anim = new Group();
  root.add(anim);

  const inkColor = new Color(colors.ink);
  const paperColor = new Color(colors.paper);
  const accentColor = new Color(colors.accent);
  const surfaceColor = new Color(colors.surface);

  // --- outer bezel plate (machined metal base) ---
  const outerGeo = new BoxGeometry(1.72, 0.58, 0.06);
  const outerMat = new MeshPhysicalNodeMaterial({
    color: surfaceColor,
    metalness: 0.45,
    roughness: 0.6,
    clearcoat: 0.15,
    clearcoatRoughness: 0.35,
  });
  const outer = new Mesh(outerGeo, outerMat);
  outer.position.set(0, 0, -0.03);
  anim.add(outer);

  // --- thin accent edge sliver (<=10% of frame, visible rim only) ---
  const edgeGeo = new BoxGeometry(1.66, 0.52, 0.02);
  const edgeMat = new MeshBasicNodeMaterial({ color: accentColor });
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.set(0, 0, -0.01);
  anim.add(edge);

  // --- inner raised brushed-metal surface (clickable face) ---
  const innerGeo = new BoxGeometry(1.62, 0.48, 0.1);
  const innerMat = new MeshPhysicalNodeMaterial({
    color: inkColor,
    metalness: 0.5,
    roughness: 0.52,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
  });
  const inner = new Mesh(innerGeo, innerMat);
  inner.position.set(0, 0, 0.02);
  anim.add(inner);

  let brushedTex = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = SRGBColorSpace;
      tex.wrapS = tex.wrapT = RepeatWrapping;
      tex.repeat.set(1.5, 1);
      brushedTex = tex;
      innerMat.map = tex;
      innerMat.needsUpdate = true;
    }).catch(() => {});
  }

  // --- label text (mono, CTA style) ---
  const textObj = ctx.fontAtlas.createText(labelText, {
    fontSize: fontSizePx,
    color: paperColor.getHexString ? `#${paperColor.getHexString()}` : colors.paper,
    align: 'center',
    letterSpacingPx: 1.5,
  });
  textObj.position.set(0, 0, 0.08);
  anim.add(textObj);

  // --- contact shadow plane (grounded, radial falloff via TSL) ---
  const shadowGeo = new PlaneGeometry(2.4, 1.2, 1, 1);
  const shadowMat = new MeshBasicNodeMaterial({
    color: vec3(0, 0, 0),
    transparent: true,
    depthWrite: false,
    side: DoubleSide,
  });
  const centeredUv = uv().sub(0.5);
  const dist = length(centeredUv.mul(vec3(1.0, 1.8, 1.0).xy ?? centeredUv));
  const falloff = float(1.0).sub(smoothstep(0.05, 0.5, dist));
  shadowMat.opacityNode = falloff.mul(0.5);
  const shadowPlane = new Mesh(shadowGeo, shadowMat);
  shadowPlane.position.set(0, -0.42, -0.05);
  anim.add(shadowPlane);

  // --- rim/accent light, node-local, intensity capped ---
  const rimLight = new PointLight(accentColor, 0.9, 4, 2);
  rimLight.position.set(0, 0.35, 1.1);
  anim.add(rimLight);

  // ------------------------------------------------------------------
  // Motion: weighted-settle entrance + hover tilt + press-down
  // ------------------------------------------------------------------
  anim.position.set(0, -0.15, 0);
  anim.scale.set(0.98, 0.98, 0.98);
  const timelines = [];

  const entrance = gsap.timeline();
  entrance.to(anim.position, { y: 0, duration: 0.7, ease: 'power3.out' });
  entrance.to(anim.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.35, ease: 'power2.out' }, 0.1);
  entrance.to(anim.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0.35);
  timelines.push(entrance);

  // idle breathing (single slow transform, <=2%)
  const idle = gsap.timeline({ repeat: -1, yoyo: true });
  idle.to(anim.scale, { x: 1.015, y: 1.015, z: 1.015, duration: 2.6, ease: 'sine.inOut', delay: 1.0 });
  timelines.push(idle);

  let pressTween = null;
  let hoverTween = null;

  root.userData.handlers = {
    pointerenter: () => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(anim.rotation, { x: -0.08, duration: 0.3, ease: 'power2.out' });
      timelines.push(hoverTween);
    },
    pointerleave: () => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(anim.rotation, { x: 0, duration: 0.3, ease: 'power2.out' });
      timelines.push(hoverTween);
    },
    pointerdown: () => {
      if (pressTween) pressTween.kill();
      pressTween = gsap.to(anim.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
      timelines.push(pressTween);
    },
    pointerup: () => {
      if (pressTween) pressTween.kill();
      pressTween = gsap.to(anim.scale, { x: 1, y: 1, z: 1, duration: 0.16, ease: 'back.out(2)' });
      timelines.push(pressTween);
      ctx.emit('navigate', { to: 'checkout' });
    },
  };

  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl && tl.kill());
    if (hoverTween) hoverTween.kill();
    if (pressTween) pressTween.kill();

    outerGeo.dispose();
    outerMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    innerGeo.dispose();
    innerMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();

    if (brushedTex) brushedTex.dispose();

    if (textObj?.geometry) textObj.geometry.dispose?.();
    if (textObj?.material) textObj.material.dispose?.();

    anim.remove(rimLight);
    rimLight.dispose?.();

    root.clear();
  };

  return root;
}
